            badgeLabel = "अध्याय १९ • CHAPTER 19",
            title = "धर्मको नाममा गरिने पाखण्ड",
            subtitle = "बाहिरी आडम्बर र भित्री आचरणबीचको खाडल",
            introduction = "निधारभरि टीका, गलामा माला र ओठमा भगवान्को नाम; तर व्यवहारमा चाहिँ नाफाखोरी, घुसखोरी र कमजोरमाथि थिचोमिचो। जब धार्मिक पहिचान नै अनैतिक काम छोप्ने खास्टो बन्छ, तब पाखण्डको जन्म हुन्छ।",
            paragraphs = listOf(
                "हाम्रो समाजमा यस्ता दृश्यहरू बग्रेल्ती देखिन्छन्—दिनभरि तराजुमा ठगी गर्ने वा कार्यालयमा सेवाग्राहीसँग घुस माग्ने मानिस साँझ परेपछि मन्दिरमा गएर सबैभन्दा ठूलो घण्टी बजाउँछ र हजार रुपैयाँ भेटी चढाएर भगवान्सँग 'हिसाब बराबर' गरेको ठान्छ! यदि भगवान् साँच्चै हुनुहुन्छ भने पनि के उहाँलाई घुसको पैसाले किन्न सकिन्छ होला?",
                "अर्को पाखण्ड हेरौँ: ढुङ्गाको नागको मूर्तिमा कचौराका कचौरा दूध खन्याइन्छ, तर घरको आँगनमा काम गर्ने गरीब मजदुरको बच्चालाई एक गिलास दूध दिन लोभ गरिन्छ। कुमारी कन्याको पूजा गरेर गोडा धोइन्छ, तर घरभित्रैकी बुहारी वा छोरीलाई दाइजो र परम्पराको नाममा आँसु पिएर बाँच्न बाध्य पारिन्छ। पितृ उद्धारका नाममा मृत्युपछि चौरासी व्यञ्जन र भव्य श्राद्ध गरिन्छ, तर बाँचुन्जेल बुढा बाबुआमालाई एक गिलास तातो पानी र मीठो बोली दिन फुर्सद हुँदैन।",
                "किन हुन्छ यस्तो? किनभने आचरण सुधार्नु गाह्रो काम हो, तर अनुष्ठान (Ritual) गर्नु सजिलो काम हो। इमानदार बन्न, रिस र लोभ त्याग्न र अरूको हक नमार्न दैनिक आत्मसंयम चाहिन्छ। तर फूलपाती चढाउन, तीर्थ घुम्न वा व्रत बस्न त केवल थोरै पैसा र शारीरिक नियम मात्र चाहिन्छ। जब समाजले मानिसको मूल्याङ्कन उसको इमानदारीले होइन, उसले लगाएको बाहिरी धार्मिक चिह्न र भोजभतेरको तडकभडकले गर्न थाल्छ, तब पाखण्ड मौलाउँछ।",
                "यहाँनेर म पूर्ण निष्पक्षताका साथ एउटा कुरा जोड्न चाहन्छु—पाखण्ड (Hypocrisy) केवल धार्मिक मानिसहरूको मात्र पेवा होइन। यो एक मानवीय कमजोरी हो। आफूलाई आधुनिक, प्रगतिशील वा नास्तिक भन्ने मानिसहरूमा पनि उत्तिकै पाखण्ड हुन सक्छ। बाहिर तर्क र मानवताको ठूला कुरा गर्ने तर घरमा श्रीमतीलाई हेप्ने वा व्यवहारमा अहंकारी र स्वार्थी हुने गैर-धार्मिक मानिसहरू पनि समाजमा भेटिन्छन्।",
                "त्यसैले समस्या आस्तिक वा नास्तिक लेबलको मात्र होइन; समस्या 'देखावटीपन' को हो। तर धर्मको नाममा हुने पाखण्ड यसकारण अझ बढी घातक हुन्छ, किनभने त्यसले 'पवित्रता' को खोल ओढेको हुन्छ र उसलाई प्रश्न गर्नेहरूलाई उल्टै 'अधर्मी' को आरोप लगाउँछ।",
                "कबीरले शताब्दीयौँपहिले यही पाखण्डमाथि प्रहार गर्दै भनेका थिए—'पाथर पूजे हरि मिले, तो मैं पूजूँ पहार; ताते ये चाकी भली, पीस खाए संसार।' (यदि ढुङ्गा पुजेर भगवान् मिल्ने भए म पहाडै पुज्थेँ; त्योभन्दा त घरको जाँतो बेस छ जसले पिठो पिसेर संसारको भोक मेट्छ।)",
