            badgeLabel = "अध्याय २० • CHAPTER 20",
            title = "सबै धर्म एउटै कुरा भन्छन्?",
            subtitle = "धार्मिक समानताको लोकप्रिय भनाइ र दार्शनिक भिन्नताहरूको यथार्थ",
            introduction = "'जुन बाटो हिँडे पनि पुग्ने ठाउँ एउटै हो, सबै धर्मले आखिर एउटै कुरा त सिकाउँछन् नि!'—सामाजिक सद्भाव कायम राख्न यो भनाइ निकै सुन्दर र उपयोगी सुनिन्छ। तर के दार्शनिक र सैद्धान्तिक दृष्टिले यो भनाइ पूर्णतः सत्य छ?",
            paragraphs = listOf(
                "जब मानिसहरू 'सबै धर्म एउटै हुन्' भन्छन्, उनीहरूको मनसाय प्रायः असल नै हुन्छ। उनीहरू भन्न खोजिरहेका हुन्छन् कि धर्मको नाममा झगडा नगरौँ, मिलेर बसौँ। सामाजिक शान्तिका लागि यो भावना स्वागतयोग्य छ। तर एक विचारशील पाठकका रूपमा हामीले सद्भावना र तथ्यबीचको फरक छुट्याउन सक्नुपर्छ।",
                "के साँच्चै संसारका प्रमुख धर्महरूका मूल विश्वासहरू एउटै छन् त? तुलना गरेर हेरौँ। अब्राहमिक धर्महरू (इस्लाम, ईसाई र यहूदी) ले भन्छन्—ईश्वर एकमात्र हुनुहुन्छ, उहाँ निराकार वा विशिष्ट हुनुहुन्छ, मानिसको जीवन एकपटक मात्र हुन्छ, र मृत्युपछि अन्तिम न्यायको दिन (Judgment Day) का आधारमा अनन्त स्वर्ग वा नरक मिल्छ।",
                "अर्कोतिर, हिन्दु परम्पराले बहुदेववाददेखि अद्वैत ब्रह्मसम्मको कुरा गर्छ र भन्छ—आत्मा अमर छ र कर्मअनुसार बारम्बार पुनर्जन्म (Reincarnation) भइरहन्छ। अनि बुद्ध धर्मले त झन् क्रान्तिकारी कुरा गर्छ—त्यहाँ न कुनै सृष्टिकर्ता ईश्वर (Creator God) को स्थान छ, न त स्थायी आत्मा (अनात्मवाद / Anatta) को नै! जैन र चार्वाक दर्शनका मान्यताहरू अझै फरक छन्।",
                "अब भन्नुहोस्: 'सृष्टिकर्ता ईश्वर हुनुहुन्छ' भन्नु र 'सृष्टिकर्ता ईश्वर हुनुहुन्न' भन्नु; 'पुनर्जन्म हुन्छ' भन्नु र 'एकपटक मात्र जीवन हुन्छ' भन्नु; 'मूर्तिपूजा पवित्र हो' भन्नु र 'मूर्तिपूजा अक्षम्य पाप हो' भन्नु—के यी सबै एउटै कुरा हुन्? बिल्कुलै होइनन्। यी त परस्पर विरोधी (Mutually Exclusive) दार्शनिक दाबीहरू हुन्।",
                "त्यसो भए धर्महरूबीच समानता चाहिँ केमा छ त? समानता छ—आधारभूत मानवीय नैतिकतामा। झूट नबोल, चोरी नगर, कमजोरलाई मद्दत गर, र अरूप्रति दया राख भन्ने शिक्षा लगभग सबै धर्महरूमा पाइन्छ। तर ध्यान दिनुपर्ने कुरा के हो भने, यो नैतिक नियम कुनै विशेष धर्मको आविष्कार होइन; यो त मानव समाज टिक्नका लागि चाहिने सार्वभौम मानवीय नियम (Golden Rule) हो।",
                "जब हामी 'सबै धर्मले एउटै कुरा भन्छन्' भनेर सतही सरलीकरण गर्छौँ, तब हामीले विभिन्न दार्शनिक परम्पराहरूबीचको गहन वैचारिक बहसलाई त बेवास्ता गर्छौँ नै, साथै प्रत्येक परम्पराभित्र रहेका विशिष्ट समस्या र सुधारको आवश्यकतालाई पनि ढाकछोप गर्छौँ।",
                "साँचो सहिष्णुता (Tolerance) भनेको 'हामी सबैको विचार एउटै छ' भन्ने झूटो दाबी गर्नु होइन। साँचो सहिष्णुता त 'हाम्रा दार्शनिक र धार्मिक मान्यताहरू एकअर्काभन्दा निकै फरक छन्, तर ती भिन्नताका बाबजुद हामी एकअर्काको बाँच्ने र सोच्ने अधिकारको पूर्ण सम्मान गर्छौँ' भन्न सक्नु हो।",
                "धर्महरूका आध्यात्मिक कथा र परलोकका नक्साहरू अलग-अलग छन्; तर मानिसको पीडा, आँसु, हाँसो र प्रेमको भाषा भने संसारभर एउटै छ। र त्यही साझा भाषाको नाम धर्म होइन, मानवता हो।"
            ),
            reflectionQuestion = "के साँचो सामाजिक सद्भावका लागि सबैका विचार र विश्वास एउटै हुनुपर्छ, कि फरक विचारलाई पनि सम्मान गर्ने संस्कार चाहिन्छ?",
            memorableQuote = "धर्महरूका परलोकका नक्साहरू एकअर्कासँग बाझिन्छन्, तर धरतीमा मानिसको आँसु र मुस्कानको भाषा भने जताततै एउटै छ।",
            references = listOf("Huston Smith — The World's Religions (1958)", "Stephen Prothero — God Is Not One (2010)"),
            readingTimeMinutes = 7
